      "type_designations": []
    },
    {
      "role": "load_cell",
      "type_designations": [],
      "characteristics": {
        "requirement": "Any compatible load cell with an OIML R60 Certificate of Conformity containing the load cell types and the necessary load cell data required for the manufacturer's declaration of compatibility of modules and any particular installation requirements; a load cell marked NH is allowed only if humidity testing to R76 has been conducted on this load cell; compatibility established by the manufacturer by means of the compatibility of modules calculation."
      }
    }
  ],
